package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaEsDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sajdah_tilawah" to DuaText("Sajdah de recitación", "Mi rostro se ha postrado ante Aquel que lo creó y le hizo nacer el oído y la vista con Su fuerza y ​​poder.", "En la postración de la recitación.", "El Profeta ﷺ dijo esto en la postración de la recitación por la noche."),
        "dua_after_witr" to DuaText("Después de Witr", "Gloria al Rey, el Santísimo.", "Tres veces después del salam de witr, alzando la voz la tercera vez.", "El Profeta ﷺ dijo esto después de witr."),
        "dua_tahajjud_nur" to DuaText("Súplica de apertura de Tahajjud", "Oh Allah, a Ti pertenece la alabanza; Eres el Sustentador de los cielos, de la tierra y de todo lo que hay dentro de ellos. A Ti pertenece la alabanza; Eres la Luz de los cielos, de la tierra y de todo lo que hay en ellos. A Ti pertenece la alabanza; Tú eres la Verdad, Tu promesa es verdadera, el encuentro contigo es verdadero, Tu palabra es verdadera, el Paraíso es verdadero, el Infierno es verdadero, los Profetas son verdaderos, Muhammad ﷺ es verdadero y la Hora es verdadera.", "Al comenzar la oración nocturna (tahajjud) (la parte inicial de la dua).", "El Profeta ﷺ recitó esto al levantarse para tahajjud (la dua completa está en al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Guíame en asuntos controvertidos", "¡Oh Allah, Señor de Jibril, Mika'il e Israfil, Creador de los cielos y de la tierra, Conocedor de lo invisible y lo visible! Juzgarás entre tus siervos en lo que discrepaban. Guíame con tu permiso hacia la verdad en lo que se ha discrepado. De hecho, Tú guías a quien quieres por el camino recto.", "Al comienzo del tahajjud: para guiarnos hacia la verdad en medio del desacuerdo.", "El Profeta ﷺ comenzó su oración nocturna con esta dua."),
        "dua_going_to_mosque_nur" to DuaText("Ir a la Mezquita (Dua de la Luz)", "Oh Allah, coloca luz en mi corazón, luz en mis ojos, luz en mis oídos, luz a mi derecha, luz a mi izquierda, luz encima de mí, luz debajo de mí, luz delante de mí, luz detrás de mí y hazme luz.", "Mientras iba a la mezquita para el Fajr.", "El Profeta ﷺ recitó esto cuando salió a orar."),
        "dua_waswasa_salah" to DuaText("Waswasa durante el salat (Khinzab)", "Busco refugio en Allah de Shaytán, el maldito.", "Cuando surjan susurros satánicos durante la oración, busque refugio y escupa en seco ligeramente hacia la izquierda tres veces.", "Uthman ibn Abil-'As (RA) hizo esto y los susurros desaparecieron."),
        "dua_alimal_ghayb" to DuaText("Conocedor de lo invisible", "¡Oh Allah, Conocedor de lo invisible y lo visible, Creador de los cielos y de la tierra, Señor y Soberano de todas las cosas! Doy testimonio de que no hay más dios que Tú. Busco refugio en Ti de la maldad de mí mismo y de la maldad de Shaytán y su (llamado a) shirk.", "Por la mañana, por la tarde y antes de dormir: el Profeta ﷺ se lo enseñó a Abu Bakr (RA).", "Protección contra el mal del yo y de Shaytán."),
        "dua_fitratil_islam" to DuaText("Sobre la Fitrah del Islam", "Hemos entrado en la mañana sobre la fitrah del Islam, sobre la palabra de sinceridad, sobre la religión de nuestro Profeta Muhammad ﷺ y sobre el camino de nuestro padre Ibrahim (AS), quien era recto y musulmán, y no era politeísta.", "Por la mañana.", "Renovar la fe cada mañana."),
        "dua_amsayna_fitrah" to DuaText("Tarde sobre la Fitrah del Islam", "Hemos entrado en la noche sobre la fitrah del Islam, sobre la palabra de sinceridad, sobre la religión de nuestro Profeta Muhammad ﷺ y sobre el camino de nuestro padre Ibrahim (AS), quien era recto y musulmán, y no era politeísta.", "Por la tarde.", "Renovar la fe cada tarde."),
        "dua_tahleel_10_fajr" to DuaText("Diez Tahleel después de Fajr y Maghrib", "Nadie tiene derecho a ser adorado excepto Allah, solo, sin asociado. Suyo es el dominio y suya la alabanza; Él da vida y causa la muerte, y tiene poder sobre todas las cosas.", "Diez veces después de Fajr (y Maghrib), antes de dejar de estar sentado o hablando.", "Diez buenas obras, diez pecados borrados, diez rangos elevados y protección de Shaytán todo el día."),
        "dua_la_hawla_kanz" to DuaText("Un tesoro de Jannah", "No hay fuerza ni poder excepto en Allah.", "A menudo, en todo momento.", "Es uno de los tesoros del Paraíso."),
        "dua_four_beloved_words" to DuaText("Las cuatro palabras más queridas", "Gloria a Allah, toda alabanza es para Allah, nadie tiene derecho a ser adorado excepto Allah, y Allah es el Más Grande.", "Las palabras más amadas por Allah.", "Son más queridos por el Profeta ﷺ que todo aquello sobre lo que sale el sol."),
        "dua_two_light_words" to DuaText("Dos palabras ligeras en la lengua", "Gloria a Allah y toda alabanza es suya; Gloria a Allah, el Magnífico.", "Ligero en la lengua, pesado en la escala.", "Amado del Misericordioso, ligero en la lengua y pesado en la balanza. (El último hadiz de al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "¡Oh poseedor de majestad y honor!", "Consérvalo en dua: la instrucción ﷺ del Profeta.", "El Profeta ﷺ dijo: aférrate a 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("En tu nombre me acuesto", "En Tu nombre, Señor mío, pongo mi costado y en Tu nombre me levanto. Si tomas mi alma, ten piedad de ella, y si la sueltas, protégela como proteges a tus justos servidores.", "Después de quitar el polvo de la cama y acostarse.", "Confiar el alma a Allah antes de dormir."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Tú creaste mi alma", "Oh Allah, Tú creaste mi alma y la tomarás. Su muerte y su vida te pertenecen. Si lo mantienes vivo, protégelo, y si lo haces morir, perdónalo. Oh Allah, te pido bienestar.", "Antes de dormir – narrado por Ibn Umar (RA).", "El Profeta ﷺ instruyó diciendo esto a la hora de dormir."),
        "dua_sleep_atamana" to DuaText("Gratitud antes de dormir", "Toda alabanza es para Allah que nos alimentó, nos dio de beber, nos bastó y nos dio refugio. Cuántos hay que no tienen quien les baste ni les dé cobijo.", "Al ir a la cama.", "El Profeta ﷺ dijo esto al acostarse."),
        "dua_sleep_rabbas_samawat" to DuaText("Señor de los Cielos — Pague nuestra deuda", "¡Oh Allah, Señor de los cielos, de la tierra y del Trono Poderoso, nuestro Señor y Señor de todas las cosas, que parte la semilla y la piedra de dátil, Revelador de la Torá, el Injil y el Furqan! Busco refugio en Ti del mal de todo aquello cuyo copete sostienes. Oh Allah, Tú eres el Primero, no hay nada delante de Ti; Tú eres el Último, no hay nada después de Ti; Tú eres el Manifiesto, no hay nada por encima de Ti; Tú eres lo Oculto, no hay nada oculto para Ti. Salda nuestra deuda por nosotros y libéranos de la pobreza.", "Antes de dormir, acostarse sobre el lado derecho – enseñado a Fatimah (RA).", "Una dua para aliviar las deudas y las dificultades."),
        "dua_sleep_fear" to DuaText("Miedo o malestar al dormir", "Busco refugio en las palabras perfectas de Allah de Su ira y Su castigo, de la maldad de Sus siervos y de los susurros de los demonios y de su llegada a mí.", "Al sentir miedo o malestar mientras duerme.", "Al hacerlo, esa cosa no le hará daño."),
        "dua_waking_afani" to DuaText("Despertar: Él restauró mi alma", "Toda alabanza es para Allah, quien le dio bienestar a mi cuerpo, me devolvió el alma y me permitió recordarlo.", "Al despertar.", "Gratitud por una nueva mañana."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah es mi Señor", "Allah, Allah es mi Señor; No asocio nada con Él.", "En pena o angustia, el Profeta ﷺ se lo enseñó a Asma bint Umays (RA).", "Aferrarse al tawhid en tiempos de angustia."),
        "dua_rahmataka_arju" to DuaText("Tu misericordia espero", "Oh Allah, es Tu misericordia lo que espero, así que no me dejes solo ni siquiera por un abrir y cerrar de ojos, y arregla todos mis asuntos. No hay más dios que Tú.", "La dua del que está en apuros (Da'awat al-makrub).", "El Profeta ﷺ lo llamó el dua del que está en apuros."),
        "dua_against_enemy_ahzab" to DuaText("Contra los ejércitos del enemigo", "¡Oh Alá, Revelador del Libro, Rápido en el ajuste de cuentas! Derrota a los confederados. Oh Allah, derrótalos y sacúdelos.", "Contra el enemigo: la dua de la Batalla de los Confederados.", "La dua ﷺ del Profeta contra el enemigo."),
        "dua_anta_adudi" to DuaText("Eres mi apoyo", "Oh Allah, Tú eres mi apoyo y mi ayuda. Por Ti planeo, por Ti avanzo y por Ti lucho.", "Antes de un concurso o de un desafío importante.", "El Profeta ﷺ dijo esto en la batalla."),
        "dua_ikfinihim" to DuaText("Me basta contra ellos", "Oh Allah, basta conmigo contra ellos como quieras.", "Contra el mal de los opresores: la dua del niño en la historia de The People of the Ditch.", "Allah salvó al niño de los opresores."),
        "dua_qadarullah" to DuaText("Cuando algo malo sucede", "Es el decreto de Allah, y Él hizo lo que quiso.", "Cuando sucede algo desagradable, en lugar de decir 'si tan solo'.", "'Si tan sólo' abre la puerta a Shaytán."),
        "dua_ala_kulli_hal" to DuaText("Alabanza en cada situación", "Toda alabanza es para Allah en cada situación.", "Cuando sucede algo que no te gusta.", "El Profeta ﷺ dijo esto al enfrentarse a algo que no le gustaba."),
        "dua_dogs_barking" to DuaText("Escuchar perros ladrar por la noche", "Busco refugio en Allah de Shaytán, el maldito.", "Al oír ladrar a un perro o rebuznar a un burro por la noche.", "Ellos ven lo que tú no ves."),
        "dua_leaving_home_adilla" to DuaText("Refugio contra el extravío", "Oh Allah, busco refugio en Ti para no desviarme o ser descarriado, para no cometer un desvío o ser obligado a cometer un desvío, para no hacer nada malo o ser agraviado, para no comportarme como un tonto o ser tratado como un tonto.", "Al salir de casa — narrado por Umm Salamah (RA).", "El Profeta ﷺ recitaba esto cada vez que salía de su casa."),
        "dua_ascending_descending" to DuaText("Subiendo y bajando", "Allah es el Más Grande (al subir). — Gloria a Allah (al descender).", "En un viaje, diga 'Allahu Akbar' cuando suba y 'SubhanAllah' cuando baje.", "La práctica de los Compañeros (RA) mientras viajan."),
        "dua_traveller_sahar" to DuaText("Dua del viajero antes del amanecer", "Un oyente ha escuchado (y transmitido) nuestras alabanzas a Allah y Sus buenos favores hacia nosotros. Señor nuestro, acompáñanos y concédenos Tu favor – (digo esto) buscando refugio en Allah del Fuego.", "De viaje, antes del amanecer.", "El Profeta ﷺ dijo esto antes del amanecer cuando viajaba."),
        "dua_zawwadakallah" to DuaText("Al viajero: que Allah proporcione la Taqwa", "Que Allah te proporcione taqwa para tu viaje, perdone tus pecados y te facilite el bien dondequiera que estés.", "Al despedirse de un viajero.", "El Profeta ﷺ le dio esta dua a alguien que emprendía un viaje."),
        "dua_traveller_to_resident" to DuaText("Viajero para los que se quedan atrás", "Os encomiendo a Allah, en quien nunca se pierde la confianza.", "Dicho por el viajero al despedirse de su familia.", "Confiando la seguridad de la familia a Allah."),
        "dua_entering_village" to DuaText("Entrar a una ciudad o pueblo", "¡Oh Allah, Señor de los siete cielos y de todo lo que les da sombra, Señor de las siete tierras y de todo lo que transportan, Señor de los demonios y de todo lo que extravían, Señor de los vientos y de todo lo que dispersan! Te pedimos por el bien de este pueblo y el bien de su gente, y buscamos refugio en Ti de su mal, del mal de su gente y del mal de lo que en él hay.", "Antes de entrar en un pueblo o ciudad.", "El Profeta ﷺ recitaba esto cada vez que deseaba entrar a una ciudad."),
        "dua_vehicle_stumbles" to DuaText("Cuando el vehículo tropieza", "En nombre de Alá.", "Cuando la montura o el vehículo resbala o tropieza, en lugar de decir 'Que Shaytan perezca'.", "Decir Bismillah hace que Shaytán se encoja al tamaño de una mosca."),
        "dua_ajz_kasal_haram" to DuaText("Refugio de la debilidad y la vejez", "Oh Allah, busco refugio en Ti del desamparo y la pereza, de la cobardía y la vejez, de las pruebas de la vida y la muerte y del castigo de la tumba.", "Un dua diario integral de refugio.", "Una dua que el Profeta ﷺ hacía con frecuencia."),
        "dua_sharri_ma_amiltu" to DuaText("Refugio del mal de mis obras", "Oh Allah, busco refugio en Ti del mal de lo que he hecho y del mal de lo que no he hecho.", "Un dua del Profeta ﷺ, según Aisha (RA).", "Protección de las consecuencias tanto de lo hecho como de lo que no se hizo."),
        "dua_jahdil_bala" to DuaText("Refugio de pruebas severas", "Oh Allah, busco refugio en Ti de las pruebas severas, de ser superado por la miseria, de un decreto malvado y del regodeo de los enemigos.", "Refugio de las pruebas severas y del regodeo de los enemigos.", "El Profeta ﷺ buscó refugio de estas cuatro cosas."),
        "dua_fitnat_ghina_faqr" to DuaText("Refugio de las pruebas de la riqueza y la pobreza", "Oh Allah, busco refugio en Ti de la pereza y la vejez, del pecado y las deudas, de la prueba y el castigo de la tumba, de la prueba y el castigo del Fuego, del mal de la prueba de la riqueza y de la prueba de la pobreza.", "Refugio de las pruebas de la tumba, el Infierno, la riqueza y la pobreza (parte de la dua).", "Un dua integral de refugio del Profeta ﷺ."),
        "dua_kufr_faqr" to DuaText("Refugio de la incredulidad y la pobreza", "Oh Allah, busco refugio en Ti de la incredulidad y la pobreza, y busco refugio en Ti del castigo de la tumba. No hay más dios que Tú.", "Tres veces por la mañana y por la tarde.", "Abu Bakrah (RA) escuchó al Profeta ﷺ decir esto."),
    )
}
